<script>
  import Icon from './Icon.svelte';

  export let section = 'overview';
  export let center;
  export let onSection = () => {};
  export let onOpenFlag = () => {};
  export let onOpenPatient = () => {};

  let ownerFilter = 'all';
  let kindFilter = 'all';
  let patternFilter = 'all';
  $: visibleFlags = center.flags.filter(item => (ownerFilter === 'all' || item.owner === ownerFilter) && (kindFilter === 'all' || item.kind === kindFilter));
  $: visiblePatterns = center.patterns.filter(item => patternFilter === 'all' || item.tone === patternFilter);
  $: owners = center.owners.map(name => ({ name, count: center.flags.filter(item => item.owner === name).length }));
</script>

{#if section === 'overview'}
  <section class="ci-command" aria-label="Center intelligence summary">
    <div class="ci-command-main"><div class="ci-command-kicker"><span class="intel-status-dot"></span> LIVE WORKSPACE / TODAY</div><h2>See what needs <em>attention.</em></h2><p>{center.stats.highPriority} priority {center.stats.highPriority === 1 ? 'item needs' : 'items need'} a human check. The signals below point to source records and named owners; they are prompts to review, not judgments about staff or patients.</p><button type="button" on:click={() => onSection('work')}>Review work gaps <Icon name="arrow" size={16}/></button></div>
    <div class="ci-command-counts"><div><span>PRIORITY CHECKS</span><strong>{String(center.stats.highPriority).padStart(2,'0')}</strong><small>Ownership and aged drafts</small></div><div><span>DOCUMENTATION</span><strong>{String(center.stats.documentationGaps).padStart(2,'0')}</strong><small>Notes and agreements to review</small></div><div><span>PATIENT SIGNALS</span><strong>{String(center.patterns.length).padStart(2,'0')}</strong><small>Evidence linked observations</small></div></div>
  </section>
  <section class="ci-vitals" aria-label="Center statistics"><div><span>ACTIVE PATIENTS</span><strong>{center.stats.activePatients}</strong><small>Across current programs</small></div><div><span>BEDS OCCUPIED</span><strong>{center.stats.occupiedBeds}<small> / {center.stats.totalBeds}</small></strong><small>Residential capacity</small></div><div><span>OPEN INQUIRIES</span><strong>{center.stats.openInquiries}</strong><small>Admissions pipeline</small></div><div><span>SESSIONS TODAY</span><strong>{center.stats.sessionsToday}</strong><small>Center schedule</small></div><div><span>FOLLOW-UPS DUE</span><strong>{center.stats.dueFollowups}</strong><small>Today or earlier</small></div></section>
  <div class="ci-home-grid"><section class="ci-home-work"><div class="ci-section-header"><div><span>01 / TEAM FOLLOW-THROUGH</span><h2>Work that needs a check</h2><p>Incomplete handoffs and records, with the source and person responsible.</p></div><button type="button" on:click={() => onSection('work')}>View all {center.flags.length} <Icon name="arrow" size={15}/></button></div><div class="ci-preview-list">{#each center.flags.slice(0,5) as flag}<button type="button" class="ci-preview-row" on:click={() => onOpenFlag(flag)}><span class:high={flag.priority === 'high'} class="ci-priority-mark"></span><span class="ci-preview-copy"><strong>{flag.title}</strong><small>{flag.subject} · {flag.owner} · {flag.sourceIds.join(', ')}</small></span><span class="ci-preview-kind">{flag.kind}</span><Icon name="arrow" size={15}/></button>{:else}<p class="ci-empty">No work gaps found in the current records.</p>{/each}</div></section><section class="ci-home-patterns"><div class="ci-section-header"><div><span>02 / PATIENT PATTERNS</span><h2>Signals with context</h2><p>Multiple records, one practical question.</p></div><button type="button" on:click={() => onSection('patterns')}>Explore <Icon name="arrow" size={15}/></button></div><div class="ci-pattern-preview-list">{#each center.patterns.slice(0,3) as pattern}<button type="button" class="ci-pattern-preview" on:click={() => onOpenPatient(pattern.patientId,pattern.tab)}><span class:positive={pattern.tone === 'positive'} class:watch={pattern.tone === 'watch'} class="ci-pattern-glyph"><Icon name={pattern.tone === 'positive' ? 'check' : pattern.tone === 'watch' ? 'clock' : 'sparkle'} size={17}/></span><span><strong>{pattern.title}</strong><small>{pattern.patientName} · {pattern.sourceIds.length} linked records</small></span><Icon name="arrow" size={15}/></button>{/each}</div></section></div>
  <section class="ci-owner-strip"><div><span>03 / ACCOUNTABILITY</span><h2>Who owns the open checks?</h2><p>Counts help coordinate work. Open the ledger to inspect each item before following up.</p></div><div class="ci-owner-list">{#each owners as owner}<button type="button" on:click={() => onSection('work')}><span>{owner.name}</span><strong>{owner.count}</strong></button>{/each}</div></section>
{:else if section === 'work'}
  <section class="ci-subhero"><div><span>01 / WORK QUALITY</span><h2>Follow-through, <em>visible.</em></h2><p>These flags describe unfinished records and handoffs. A flag stays visible until its source record changes; opening it takes you to the original workflow.</p></div><div><strong>{center.flags.length}</strong><span>OPEN CHECKS</span></div></section>
  <section class="ci-ledger"><div class="ci-section-header"><div><span>FILTER THE WORK</span><h2>Attention ledger</h2><p>Use owner and record type to narrow the list.</p></div><span class="ci-ledger-count">{visibleFlags.length} SHOWN</span></div><div class="ci-filterline"><label>Owner <select bind:value={ownerFilter}><option value="all">All owners</option>{#each center.owners as owner}<option value={owner}>{owner}</option>{/each}</select></label><label>Record type <select bind:value={kindFilter}><option value="all">All types</option><option>Clinical notes</option><option>Documents</option><option>Intake record</option><option>Ownership</option></select></label><button type="button" on:click={() => {ownerFilter = 'all'; kindFilter = 'all';}}>Clear filters</button></div><div class="ci-ledger-head"><span>CHECK / SOURCE</span><span>OWNER</span><span>PRIORITY</span><span>ACTION</span></div>{#each visibleFlags as flag}<div class="ci-ledger-row"><div><span class="ci-ledger-kind">{flag.kind} · {flag.sourceIds.join(', ')}</span><strong>{flag.title}</strong><p>{flag.detail}</p></div><div class="ci-ledger-owner">{flag.owner}<small>{flag.subject}</small></div><div><span class:high={flag.priority === 'high'} class="ci-priority-pill">{flag.priority === 'high' ? 'Priority' : 'Review'}</span></div><button type="button" on:click={() => onOpenFlag(flag)}>{flag.action} <Icon name="arrow" size={14}/></button></div>{:else}<p class="ci-empty">No checks match these filters.</p>{/each}</section>
  <div class="ci-guidance"><Icon name="shield" size={17}/><p><strong>A record gap is not a staff performance verdict.</strong> The owner shown is the person currently recorded on the work item. Confirm context and workload with the team before taking action.</p></div>
{:else if section === 'patterns'}
  <section class="ci-subhero ci-pattern-hero"><div><span>01 / PATIENT PATTERNS</span><h2>Notice the change. <em>Check the context.</em></h2><p>Signals combine attendance, notes, preferences and upcoming contact. They identify a question for the care team; they do not diagnose, predict outcomes, or decide treatment.</p></div><div><strong>{center.patterns.length}</strong><span>LINKED SIGNALS</span></div></section>
  <section class="ci-pattern-page"><div class="ci-section-header"><div><span>REVIEW THE EVIDENCE</span><h2>Patient signals</h2><p>Each observation includes the records that led to it and a practical next step.</p></div><label>Show <select bind:value={patternFilter}><option value="all">All signals</option><option value="attention">Needs attention</option><option value="watch">To check</option><option value="positive">Continuity noted</option></select></label></div><div class="ci-pattern-rows">{#each visiblePatterns as pattern, index}<article class="ci-pattern-row"><div class="ci-pattern-number">0{index + 1}</div><div class="ci-pattern-body"><div class="ci-pattern-overline"><span class:positive={pattern.tone === 'positive'} class:watch={pattern.tone === 'watch'} class="ci-pattern-tone">{pattern.tone === 'positive' ? 'CONTINUITY' : pattern.tone === 'watch' ? 'CHECK CONTEXT' : 'NEEDS ATTENTION'}</span><span>{pattern.patientName} · {pattern.patientId}</span></div><h3>{pattern.title}</h3><p>{pattern.detail}</p><div class="ci-source-chips"><span>SOURCE RECORDS</span>{#each pattern.sourceIds as id}<code>{id}</code>{/each}</div></div><div class="ci-pattern-actions"><button type="button" on:click={() => onOpenPatient(pattern.patientId,pattern.tab)}>{pattern.action} <Icon name="arrow" size={15}/></button><button type="button" on:click={() => onOpenPatient(pattern.patientId,'AI review')}>Full case review <Icon name="sparkle" size={14}/></button></div></article>{:else}<p class="ci-empty">No patient signals match this view.</p>{/each}</div></section>
  <div class="ci-guidance"><Icon name="shield" size={17}/><p><strong>Staff review is required.</strong> These are record based observations in a fictional preview. Open the patient file to check notes, documents, attendance and consent before deciding any next step.</p></div>
{/if}
